 TextView text(String value,float size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(white);t.setFontFeatureSettings("kern");t.setGravity(Gravity.CENTER);return t;}
 LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
