 void render(){root=new GestureRoot();root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,0,0,insets.getSystemWindowInsetBottom());return insets;});root.addView(new Wallpaper(),new FrameLayout.LayoutParams(-1,-1));home=column();home.setPadding(dp(16),statusInset()+dp(22),dp(16),dp(12));root.addView(home,new FrameLayout.LayoutParams(-1,-1));buildHome();setContentView(root);if(showingDrawer)buildDrawer();}
 void buildHome(){LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);LinearLayout time=column();time.setPadding(dp(8),0,0,0);clock=text("",66);clock.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);clock.setTypeface(android.graphics.Typeface.create("sans-serif-thin",0));date=text("",18);date.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);time.addView(clock,new LinearLayout.LayoutParams(-1,dp(78)));time.addView(date,new LinearLayout.LayoutParams(-1,dp(30)));header.addView(time,new LinearLayout.LayoutParams(0,-2,1));
 LinearLayout weather=new LinearLayout(this);weather.setGravity(Gravity.CENTER);weather.setPadding(dp(10),0,dp(10),0);weather.setBackground(rounded(0x505B5986,30));WeatherIcon weatherIcon=new WeatherIcon();weather.addView(weatherIcon,new LinearLayout.LayoutParams(dp(37),dp(37)));TextView weatherText=text("Tap to set up",16);weather.addView(weatherText,new LinearLayout.LayoutParams(-2,-2));weather.setContentDescription("Weather. Tap to set up a weather app");header.addView(weather,new LinearLayout.LayoutParams(dp(160),dp(48)));weather.setOnClickListener(v->weatherSetup());home.addView(header,new LinearLayout.LayoutParams(-1,dp(114)));updateClock();
 View space=new View(this);home.addView(space,new LinearLayout.LayoutParams(1,0,1));
 App[] favorites={find("com.android.vending"),find("com.clearchoice"),find("com.android.settings"),find("com.google.android.documentsui","com.android.documentsui","com.google.android.apps.nbu.files"),find("com.google.android.apps.photos"),find("com.google.android.contacts","com.android.contacts"),find("com.google.android.calculator","com.android.calculator2"),find("com.google.android.deskclock","com.android.deskclock")};
 for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);for(int col=0;col<4;col++){App app=favorites[row*4+col];View cell=app==null?new View(this):tile(app,false);line.addView(cell,new LinearLayout.LayoutParams(0,dp(100),1));}home.addView(line);}
 TextView indicator=text("●",10);indicator.setAlpha(.9f);home.addView(indicator,new LinearLayout.LayoutParams(-1,dp(38)));LinearLayout dock=new LinearLayout(this);dock.setGravity(Gravity.CENTER);dock.setPadding(dp(5),dp(8),dp(5),dp(8));GradientDrawable dockBackground=rounded(0x374E527D,30);dockBackground.setStroke(dp(1),0x1FFFFFFF);dock.setBackground(dockBackground);String[][] names={{"com.google.android.dialer","com.android.dialer","Phone"},{"com.google.android.apps.messaging","Messages"},{"com.android.chrome","Chrome"},{"com.android.camera2","com.google.android.GoogleCamera","Camera"}};for(String[] options:names){App app=find(options);View cell=app==null?new View(this):tile(app,true);dock.addView(cell,new LinearLayout.LayoutParams(0,dp(70),1));}home.addView(dock,new LinearLayout.LayoutParams(-1,dp(90)));}
 final class WeatherIcon extends View {Paint p=new Paint(3);WeatherIcon(){super(HomeActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(0xFFFFD400);c.drawCircle(w*.57f,h*.37f,w*.23f,p);p.setColor(0xFFF5F6FF);c.drawCircle(w*.36f,h*.54f,w*.24f,p);c.drawCircle(w*.21f,h*.67f,w*.15f,p);c.drawRoundRect(w*.1f,h*.56f,w*.72f,h*.84f,w*.12f,w*.12f,p);}}
 void updateClock(){if(clock==null)return;Date now=new Date();clock.setText(android.text.format.DateFormat.getTimeFormat(this).format(now));date.setText(new SimpleDateFormat("EEE, d MMMM",Locale.getDefault()).format(now));}
 View tile(App app,boolean dock){LinearLayout tile=column();tile.setGravity(Gravity.CENTER);tile.setPadding(dp(2),dp(4),dp(2),dp(4));ImageView icon=new ImageView(this);icon.setImageDrawable(app.icon);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);tile.addView(icon,new LinearLayout.LayoutParams(dp(58),dp(dock?53:51)));if(!dock){TextView label=text(app.label,14);label.setMaxLines(1);label.setEllipsize(TextUtils.TruncateAt.END);label.setPadding(0,dp(6),0,0);tile.addView(label,new LinearLayout.LayoutParams(-1,dp(27)));}tile.setContentDescription(app.label);tile.setFocusable(true);tile.setBackgroundResource(android.R.drawable.list_selector_background);tile.setOnClickListener(v->launch(app));tile.setOnLongClickListener(v->{startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+app.pkg)));return true;});return tile;}
 void showDrawer(){if(showingDrawer)return;showingDrawer=true;query="";buildDrawer();}
 void buildDrawer(){home.setVisibility(View.GONE);drawer=column();drawer.setPadding(dp(18),statusInset()+dp(16),dp(18),dp(12));drawer.setBackgroundColor(0xC7141E36);root.addView(drawer,new FrameLayout.LayoutParams(-1,-1));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(16),0,dp(10),0);bar.setBackground(rounded(0x293F567F,28));search=new EditText(this);search.setSingleLine();search.setTextSize(16);search.setTextColor(white);search.setHintTextColor(0xBBDCE5FA);search.setHint("Search apps");search.setBackgroundColor(Color.TRANSPARENT);search.setPadding(dp(6),0,0,0);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);bar.addView(search,new LinearLayout.LayoutParams(0,dp(50),1));TextView settings=text("⋮",26);settings.setContentDescription("Launcher options");settings.setOnClickListener(v->new AlertDialog.Builder(this).setItems(new String[]{"Android settings","Default home app"},(d,n)->startActivity(new Intent(n==0?android.provider.Settings.ACTION_SETTINGS:android.provider.Settings.ACTION_HOME_SETTINGS))).show());bar.addView(settings,new LinearLayout.LayoutParams(dp(38),dp(48)));drawer.addView(bar);TextView heading=text("All apps",13);heading.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);heading.setAlpha(.65f);heading.setPadding(dp(8),0,0,0);drawer.addView(heading,new LinearLayout.LayoutParams(-1,dp(48)));scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);grid=new GridLayout(this);grid.setColumnCount(4);grid.setAlignmentMode(GridLayout.ALIGN_BOUNDS);scroll.addView(grid,new ScrollView.LayoutParams(-1,-2));drawer.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));fillGrid(query);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();fillGrid(query);}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((v,id,event)->{for(App a:apps)if(a.label.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT))){launch(a);return true;}if(!query.trim().isEmpty())try{startActivity(new Intent(Intent.ACTION_WEB_SEARCH).putExtra(android.app.SearchManager.QUERY,query));}catch(ActivityNotFoundException e){Toast.makeText(this,"No matching app",Toast.LENGTH_SHORT).show();}return true;});drawer.setFocusableInTouchMode(true);drawer.requestFocus();}
 void fillGrid(String query){if(grid==null)return;grid.removeAllViews();String q=query.trim().toLowerCase(Locale.ROOT);for(App a:apps)if(q.isEmpty()||a.label.toLowerCase(Locale.ROOT).contains(q)){GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(GridLayout.UNDEFINED),GridLayout.spec(GridLayout.UNDEFINED,1f));p.width=0;p.height=dp(96);grid.addView(tile(a,false),p);}if(grid.getChildCount()==0){TextView empty=text("No matching apps",15);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(0),GridLayout.spec(0,4));p.width=-1;p.height=dp(100);grid.addView(empty,p);}}
 void showHome(){hideKeyboard();if(drawer!=null){root.removeView(drawer);drawer=null;}showingDrawer=false;query="";home.setVisibility(View.VISIBLE);updateClock();}
 void hideKeyboard(){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);}
 void weatherSetup(){String saved=getPreferences(0).getString("weather","");for(App a:apps)if(a.component.flattenToString().equals(saved)){launch(a);return;}String[] labels=new String[apps.size()];for(int i=0;i<apps.size();i++)labels[i]=apps.get(i).label;new AlertDialog.Builder(this).setTitle("Choose your weather app").setItems(labels,(d,n)->{getPreferences(0).edit().putString("weather",apps.get(n).component.flattenToString()).apply();launch(apps.get(n));}).setNegativeButton("Cancel",null).show();}
 final class GestureRoot extends FrameLayout {float x,y;boolean intercept;GestureRoot(){super(HomeActivity.this);}public boolean onInterceptTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();intercept=false;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dy=e.getY()-y,dx=Math.abs(e.getX()-x);if(Math.abs(dy)>dp(55)&&Math.abs(dy)>dx*1.4f&&(!showingDrawer&&dy<0||showingDrawer&&dy>0&&scroll!=null&&scroll.getScrollY()==0&&!search.hasFocus())){intercept=true;return true;}}return false;}public boolean onTouchEvent(MotionEvent e){if(intercept&&e.getActionMasked()==MotionEvent.ACTION_UP){if(showingDrawer)showHome();else showDrawer();intercept=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL)intercept=false;return true;}}
 final class Wallpaper extends View {Paint p=new Paint(3);Wallpaper(){super(HomeActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setShader(new LinearGradient(0,0,w,h,new int[]{0xff111327,0xff20204E,0xff10122C},null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);
 Path upper=new Path();upper.moveTo(w*.50f,-h*.06f);upper.cubicTo(w*.39f,h*.12f,w*.29f,h*.22f,-w*.13f,h*.31f);ribbon(c,upper,w*.46f,new int[]{0xff161A38,0xff46589C,0xff879BE9});
 Path middle=new Path();middle.moveTo(w*1.17f,h*.33f);middle.cubicTo(w*.58f,h*.47f,w*.86f,h*.54f,-w*.16f,h*.68f);ribbon(c,middle,w*.42f,new int[]{0xff212247,0xff343A79,0xff4E6BAE});
 Path lower=new Path();lower.moveTo(w*1.18f,h*.50f);lower.cubicTo(w*.63f,h*.55f,w*.23f,h*.67f,-w*.22f,h*.91f);ribbon(c,lower,w*.35f,new int[]{0xff2C3168,0xff5552A0,0xffA09BED});
 p.setShader(new LinearGradient(0,h*.85f,w,h,new int[]{0x0010142B,0xA010142B},null,Shader.TileMode.CLAMP));p.setStyle(Paint.Style.FILL);c.drawRect(0,h*.85f,w,h,p);p.setShader(null);}
 void ribbon(Canvas c,Path path,float width,int[] colors){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(width);p.setShader(new LinearGradient(0,0,getWidth(),getHeight(),colors,null,Shader.TileMode.CLAMP));c.drawPath(path,p);p.setShader(null);for(int i=12;i>=1;i--){p.setStrokeWidth(dp(i*2));p.setColor(Color.argb(5,136,155,255));c.drawPath(path,p);}p.setStrokeWidth(dp(.65f));p.setColor(0x608DA4F3);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
